mutation WaffleXEQuery($input) {
  waffle_xas {
    waffle_xan
    waffle_xs
    waffle_xe_root {
      purpose_public_keys {
        purpose_public_ek
        purpose_public_ik
        purpose_public_ik_sig
        purpose_public_ik_enc_certificate
        purpose_dummy_ciphertext
        purpose_dummy_nonce
        waffle_unique_ids
        waffle_d {
          waffle_di
          waffle_xps {
            waffle_hcbc
          }
        }
      }
    }
  }
}
